validation_logic:
if not manufacturer_name:
    return 'POTENTIAL_NON_COMPLIANCE', 'Missing manufacturer name'
if not manufacturer_address:
    return 'POTENTIAL_NON_COMPLIANCE', 'Missing manufacturer address'
return 'NEEDS_HUMAN_VERIFICATION', 'Verify name and address details against the official registration registry'

if not country_of_origin:
    return 'POTENTIAL_NON_COMPLIANCE', 'Missing country of origin on imported package'
return 'NEEDS_HUMAN_VERIFICATION', 'Verify authenticity of country of origin against the Bill of Entry'

if not generic_name:
    return 'POTENTIAL_NON_COMPLIANCE', 'Missing common or generic name of commodity'
return 'NEEDS_HUMAN_VERIFICATION', 'Verify if generic name matches standard trade categories'

if not net_quantity or not unit:
    return 'POTENTIAL_NON_COMPLIANCE', 'Missing net quantity or unit declaration'
if unit not in ['g', 'gram', 'kg', 'kilogram', 'ml', 'millilitre', 'l', 'L', 'litre', 'm', 'metre', 'cm', 'centimetre', 'N', 'U', 'number', 'unit', 'piece', 'set', 'pair']:
    return 'POTENTIAL_NON_COMPLIANCE', 'Invalid net quantity unit used'
return 'NEEDS_HUMAN_VERIFICATION', 'Physical weighing/measurement of net quantity is required to prove compliance'

if not best_before and not use_by:
    return 'POTENTIAL_NON_COMPLIANCE', 'Perishable items must declare best before or use by date'
return 'NEEDS_HUMAN_VERIFICATION', 'Check food safety or drugs act overrides for specialized perishable items'

if not MRP:
    return 'POTENTIAL_NON_COMPLIANCE', 'Missing retail sale price (MRP)'
if not mrp_currency:
    return 'POTENTIAL_NON_COMPLIANCE', 'Missing currency symbol or text (Rs / INR / ₹)'
if not mrp_taxes_inclusion:
    return 'POTENTIAL_NON_COMPLIANCE', 'Missing "inclusive of all taxes" declaration text'
return 'NEEDS_HUMAN_VERIFICATION', 'Verify MRP sticker alterations or price differences on shelves'

if not consumer_care_name:
    return 'POTENTIAL_NON_COMPLIANCE', 'Missing contact person or office name'
if not consumer_care_address:
    return 'POTENTIAL_NON_COMPLIANCE', 'Missing contact physical address'
if not consumer_care_phone:
    return 'POTENTIAL_NON_COMPLIANCE', 'Missing contact telephone number'
if not consumer_care_email:
    return 'POTENTIAL_NON_COMPLIANCE', 'Missing contact e-mail address'
import re
email_pattern = r'^[\w\.-]+@[\w\.-]+\.[a-zA-Z]{2,}'
if not re.match(email_pattern, consumer_care_email):
    return 'POTENTIAL_NON_COMPLIANCE', 'Invalid consumer care email format'
return 'NEEDS_HUMAN_VERIFICATION', 'Verify if helpline phone is active and email inbox is functional'

if not unit_sale_price_value or not unit_sale_price_uom:
    return 'POTENTIAL_NON_COMPLIANCE', 'Missing Unit Sale Price (USP) declaration'
expected_usp = MRP / net_quantity
if abs(unit_sale_price_value - expected_usp) > 0.05:
    return 'POTENTIAL_NON_COMPLIANCE', 'Declared USP does not mathematically match MRP and net quantity'
return 'COMPLIANT', 'Unit sale price is compliant'

if not PDP_information or not font_measurement:
    return 'NEEDS_HUMAN_VERIFICATION', 'PDP or font size details cannot be calculated from image alone'
pdp_area = PDP_information.get('area_sq_cm', 0)
char_height_mm = font_measurement.get('min_char_height_mm', 0)
is_molded = PDP_information.get('is_blown_or_molded_surface', False)

if pdp_area < 50:
    req_height = 2.0 if is_molded else 1.0
elif pdp_area >= 50 and pdp_area < 100:
    req_height = 3.0 if is_molded else 1.5
elif pdp_area >= 100 and pdp_area < 500:
    req_height = 4.0 if is_molded else 2.5
elif pdp_area >= 500 and pdp_area < 2500:
    req_height = 6.0 if is_molded else 4.0
else:
    req_height = 6.0

if char_height_mm < req_height:
    return 'POTENTIAL_NON_COMPLIANCE', f'Numeral and letter heights are below Table-I limits. Found {char_height_mm}mm, required {req_height}mm'
return 'NEEDS_HUMAN_VERIFICATION', 'Conclusive millimeter verification requires physical caliper calibration and measurement'

missing_declarations = []
mandatory = ['MRP', 'net_quantity', 'country_of_origin', 'manufacturer_packer_importer_details', 'common_generic_name', 'consumer_care_details']
for field in mandatory:
    if not ecommerce_information.get('declarations_present', {}).get(field, False):
        missing_declarations.append(field)
if missing_declarations:
    return 'POTENTIAL_NON_COMPLIANCE', f'E-commerce digital pre-purchase listing is missing mandatory declarations: {missing_declarations}'
return 'COMPLIANT', 'All mandatory pre-purchase declarations are displayed online'

if not electronic_weighing_machine_class_iii:
    return 'POTENTIAL_NON_COMPLIANCE', 'GST registered retailer selling weight/volume packages must maintain Class III weighing machine'
if smallest_division_value > 1.0:
    return 'POTENTIAL_NON_COMPLIANCE', 'Smallest division must be at least 1 g'
if not printed_receipt_facility:
    return 'POTENTIAL_NON_COMPLIANCE', 'Machine must have facility to issue a printed receipt'
return 'NEEDS_HUMAN_VERIFICATION', 'Requires physical on-site audit of the retailer weighing machine'

if not check_weigher_class_iii:
    return 'POTENTIAL_NON_COMPLIANCE', 'LPG distributor must maintain check weigher of accuracy Class III'
if not check_weigher_capacity_gte_50kg:
    return 'POTENTIAL_NON_COMPLIANCE', 'Check weigher capacity must be at least 50 kg'
if not check_weigher_smallest_division_lte_10g:
    return 'POTENTIAL_NON_COMPLIANCE', 'Check weigher smallest division must be 10 g or less (e=10g)'
return 'NEEDS_HUMAN_VERIFICATION', 'Verify if check weigher is provided physically to the delivery man'

if unit in ['dozen', 'score', 'gross', 'great_gross']:
    return 'POTENTIAL_NON_COMPLIANCE', f'Prohibited non-metric unit notation used: {unit}'
if unit in ['g', 'kg', 'ml', 'L', 'l', 'm', 'cm', 'N', 'U', 'number', 'unit', 'piece', 'set', 'pair']:
    return 'COMPLIANT', 'Compliant metric SI unit notation used'
return 'POTENTIAL_NON_COMPLIANCE', f'Non-standard unit notation detected: {unit}'

if seized_packages_count != 5:
    return 'POTENTIAL_NON_COMPLIANCE', f'Statutory seizure requires exactly 5 representative sample packages as court evidence. Found: {seized_packages_count}'
return 'NEEDS_HUMAN_VERIFICATION', 'Prosecution seizure process must be verified by a certified Legal Metrology Officer'

fill_ratio = PDP_information.get('volume_fill_ratio', 1.0)
if fill_ratio < 0.70:
    if protective_packaging_justified or machinery_requirements_justified:
        return 'NEEDS_HUMAN_VERIFICATION', 'Package has high slack-fill, but manufacturer has submitted protective/machinery justification. Officer review needed.'
    return 'POTENTIAL_NON_COMPLIANCE', f'Package is potentially deceptive due to excessive slack fill. Volume fill ratio: {fill_ratio}'
return 'NEEDS_HUMAN_VERIFICATION', 'Officer inspection required to confirm physical deceptive characteristics'

if declared_uom_type == 'length':
    mpe = 2.0 if net_quantity <= 10.0 else 1.0
elif declared_uom_type == 'area':
    mpe = 4.0 if net_quantity <= 10.0 else 1.0
else:
    mpe = 2.0

if physical_deficiency_percentage > mpe:
    return 'POTENTIAL_NON_COMPLIANCE', f'Individual deficiency exceeds Table-II MPE limits. Deficiency: {physical_deficiency_percentage}%, Limit: {mpe}%'
return 'NEEDS_HUMAN_VERIFICATION', 'Confirm physical quantity error with calibrated steel tape or actual counting'

if not advertisement_declares_net_quantity:
    return 'POTENTIAL_NON_COMPLIANCE', 'Ad mentioning MRP must contain net quantity or count declaration'
if font_size_net_quantity_pixels < font_size_mrp_pixels:
    return 'POTENTIAL_NON_COMPLIANCE', 'Font size of net quantity in advertisement must be equal to or larger than MRP font size'
return 'COMPLIANT', 'Advertisement declarations comply with Rule 31'

if not registration_contains_responsible_director_name:
    return 'POTENTIAL_NON_COMPLIANCE', 'Corporate registration application must explicitly nominate the Director responsible for violations under the Act'
return 'NEEDS_HUMAN_VERIFICATION', 'Verify registered director credentials against MCA database'

if not portal_profile_updated_annually:
    return 'POTENTIAL_NON_COMPLIANCE', 'Registered company or firm must update its details annually on the online portal'
return 'NEEDS_HUMAN_VERIFICATION', 'Verify update timestamp in online registry portal'

if not declarations_complete_prior_to_leaving_bonded_warehouse:
    return 'POTENTIAL_NON_COMPLIANCE', 'Retail packages must carry all mandatory declarations before leaving the certified AEO bonded warehouse'
return 'NEEDS_HUMAN_VERIFICATION', 'Verify certified AEO status and customs warehouse dockets'

missing = []
mandatory = ['name_address_origin', 'consumer_care', 'sizes_metric', 'MRP']
for tag in mandatory:
    if tag not in tags_declared:
        missing.append(tag)
if missing:
    return 'POTENTIAL_NON_COMPLIANCE', f'Loose garment or hosiery tags are missing mandatory details: {missing}'
return 'COMPLIANT', 'Loose garment tags are compliant'

missing = []
mandatory = ['name_address_origin_seller', 'consumer_care', 'MRP', 'net_quantity']
for field in mandatory:
    if field not in declarations_exist:
        missing.append(field)
if missing:
    return 'POTENTIAL_NON_COMPLIANCE', f'Loose online order package or page is missing declarations: {missing}'
return 'COMPLIANT', 'Loose online order declarations are compliant'

if not declarations_comply_with_mdr_2017:
    return 'POTENTIAL_NON_COMPLIANCE', 'Medical devices packages must comply strictly with the declarations and character specifications of the Medical Devices Rules, 2017'
return 'NEEDS_HUMAN_VERIFICATION', 'Requires specialized medical device labeling registration review'
